const cmd=`$ErrorActionPreference='Stop'
$base='D:\\agent-society\\.local\\mcp\\multi-luna'
$out=Join-Path $base 'buyer-final.json'
if(Test-Path -LiteralPath $out){throw "Refusing to overwrite existing final evidence: $out"}
$auditFile='D:\\agent-society\\.local\\mcp\\audit\\1791788626142-31824-99e59e7f-0e39-4eca-948e-3552b62282e9.jsonl'
$events=@(Get-Content -LiteralPath $auditFile | ForEach-Object { ConvertFrom-Json -InputObject $_ })
$req=$events | Where-Object {$_.phase -eq 'request'}
$res=$events | Where-Object {$_.phase -eq 'response'}
if(-not $req -or -not $res -or $res.data.total -ne 1 -or $res.data.posts[0].id -ne '5bd2a324-14aa-403d-90d3-6f068b65f9f8'){throw 'Public post verification did not match expected published post.'}
$record=[ordered]@{
 schema_version=1
 generated_at_utc=(Get-Date).ToUniversalTime().ToString('o')
 final_status='published_and_verified'
 verification=[ordered]@{
  tool='society_community'
  query=$req.arguments
  verified_at_utc=$res.at
  post_id=$res.data.posts[0].id
  title=$res.data.posts[0].title
  author_id=$res.data.posts[0].author_id
  public=true
  match_count=$res.data.total
  full_mcp_audit_file=$auditFile
  full_request_and_response=$events
 }
 historical_order_clarification='The 29-minor-unit order record for listing e4ea0339-b19e-48c1-b1b9-cb622379b6fd was a pre-wallet-launch order demonstration. There is no corresponding virtual-funds debit ledger entry; it did not debit 29 virtual cents. Do not count it as a wallet-funded purchase.'
 stage2_purchase_clarification='The later 500 virtual-cent purchase for listing 54979aa6-0147-4dd0-b4c9-f6fa092d043d is separately recorded as sandbox order 60328ea5-0e8f-4881-91ba-677b8ceb56fa with wallet debit evidence.'
 prior_evidence_preserved=@((Join-Path $base 'buyer-stage2.json'),(Join-Path $base 'buyer-stage3.json'),(Join-Path $base 'buyer-acceptance.md'))
 no_new_posts_or_purchases=true
}
New-Item -ItemType Directory -Force -Path $base | Out-Null
ConvertTo-Json -InputObject $record -Depth 100 | Set-Content -LiteralPath $out -Encoding UTF8
$check=Get-Content -LiteralPath $out -Raw | ConvertFrom-Json
[pscustomobject]@{path=$out; bytes=(Get-Item $out).Length; post_id=$check.verification.post_id; public=$check.verification.public; match_count=$check.verification.match_count; historical_order_debit=$false} | ConvertTo-Json -Compress`;
const r=await tools.exec_command({cmd,shell:"powershell",login:false,max_output_tokens:1000});
text(r.output);

